func TestCommandsTable(t *testing.T) {
	cmds := []cli.Command{
		{Name: "version", Summary: "Print the client's version"},
		{Name: "help", Summary: "Show usage for ajent, or details for one command"},
	}

	var b strings.Builder
	if err := Commands(&b, cmds); err != nil {
		t.Fatalf("Commands: %v", err)
	}

	want := "# Command reference\n" +
		"\n" +
		"<!-- Generated by `make docs`. Do not edit. -->\n" +
		"\n" +
		"| Command | Description |\n" +
		"| --- | --- |\n" +
		"| `ajent help` | Show usage for ajent, or details for one command |\n" +
		"| `ajent version` | Print the client's version |\n"

	if got := b.String(); got != want {
		t.Errorf("Commands() =\n%q\nwant\n%q", got, want)
	}
}

func TestCommandsExcludesHiddenAndPlaceholdersMissingSummary(t *testing.T) {
	cmds := []cli.Command{
		{Name: "gendocs", Hidden: true, Summary: "Generate reference docs"},
		{Name: "zzz", Summary: ""},
	}

	var b strings.Builder
	if err := Commands(&b, cmds); err != nil {
		t.Fatalf("Commands: %v", err)
	}

	got := b.String()
	if strings.Contains(got, "gendocs") {
		t.Errorf("Commands() included the hidden command:\n%s", got)
	}
	want := "| `ajent zzz` | (no summary) |\n"
	if !strings.Contains(got, want) {
		t.Errorf("Commands() missing placeholder row %q, got:\n%s", want, got)
	}
}

func TestCommandsEscapesPipe(t *testing.T) {
	cmds := []cli.Command{
		{Name: "search", Summary: "Search posts | findings"},
	}

	var b strings.Builder
	if err := Commands(&b, cmds); err != nil {
		t.Fatalf("Commands: %v", err)
	}

	want := "# Command reference\n" +
		"\n" +
		"<!-- Generated by `make docs`. Do not edit. -->\n" +
		"\n" +
		"| Command | Description |\n" +
		"| --- | --- |\n" +
		"| `ajent search` | Search posts \\| findings |\n"

	if got := b.String(); got != want {
		t.Errorf("Commands() =\n%q\nwant\n%q", got, want)
	}
}

func TestToolsSchemaTable(t *testing.T) {
	tools := []mcp.Tool{
		{
			Name:        "ajent_test_tool",
			Description: "Test tool for the schema table.",
			InputSchema: json.RawMessage(`{
				"type": "object",
				"properties": {
					"query": {"type": "string"},
					"limit": {"type": "integer"}
				},
				"required": ["query"],
				"additionalProperties": false
			}`),
			Annotations: &mcp.Annotations{ReadOnlyHint: true, DestructiveHint: false, OpenWorldHint: true},
		},
	}

	var b strings.Builder
	if err := Tools(&b, tools); err != nil {
		t.Fatalf("Tools: %v", err)
	}

	want := "# MCP tool reference\n" +
		"\n" +
		"<!-- Generated by `make docs`. Do not edit. -->\n" +
		"\n" +
		"## ajent_test_tool\n" +
		"\n" +
		"Test tool for the schema table.\n" +
		"\n" +
		"Read-only: yes. Destructive: no.\n" +
		"\n" +
		"### Input\n" +
		"\n" +
		"| Field | Type | Required | Description |\n" +
		"| --- | --- | --- | --- |\n" +
		"| `limit` | integer | no | |\n" +
		"| `query` | string | yes | |\n"

	if got := b.String(); got != want {
		t.Errorf("Tools() =\n%q\nwant\n%q", got, want)
	}
}

func TestToolsAnnotations(t *testing.T) {
	tools := []mcp.Tool{
		{
			Name:        "ajent_readonly",
			Description: "A read-only, non-destructive tool.",
			InputSchema: json.RawMessage(`{"type":"object","properties":{},"required":[]}`),
			Annotations: &mcp.Annotations{ReadOnlyHint: true, DestructiveHint: false, OpenWorldHint: true},
		},
		{
			Name:        "ajent_destructive",
			Description: "A destructive, non-read-only tool.",
			InputSchema: json.RawMessage(`{"type":"object","properties":{},"required":[]}`),
			Annotations: &mcp.Annotations{ReadOnlyHint: false, DestructiveHint: true, OpenWorldHint: true},
		},
		{
			Name:        "ajent_no_annotations",
			Description: "A tool with no annotations at all.",
			InputSchema: json.RawMessage(`{"type":"object","properties":{},"required":[]}`),
		},
	}

	var b strings.Builder
	if err := Tools(&b, tools); err != nil {
		t.Fatalf("Tools: %v", err)
	}
	got := b.String()

	cases := []struct {
		name string
		line string
	}{
		{"ajent_readonly", "Read-only: yes. Destructive: no.\n"},
		{"ajent_destructive", "Read-only: no. Destructive: yes.\n"},
		{"ajent_no_annotations", "Read-only: no. Destructive: no.\n"},
	}
	for _, c := range cases {
		if !strings.Contains(got, "## "+c.name+"\n") {
			t.Errorf("Tools() missing section %q, got:\n%s", c.name, got)
		}
		if !strings.Contains(got, c.line) {
			t.Errorf("Tools() missing annotations line %q for %s, got:\n%s", c.line, c.name, got)
		}
	}
}
